DROP TRIGGER IF EXISTS `after_log_quality_insert`;
DELIMITER $$
CREATE TRIGGER `after_log_quality_insert` AFTER INSERT ON `log_quality` FOR EACH ROW BEGIN
    DECLARE v_last_info VARCHAR(255);
    DECLARE v_diff_id INT;
    DECLARE v_start_time TIMESTAMP;
    DECLARE v_durasi INT;

    SELECT mcInfo INTO v_last_info 
    FROM log_quality 
    WHERE mcID = NEW.mcID AND id < NEW.id 
    ORDER BY id DESC LIMIT 1;

    IF v_last_info IS NOT NULL AND v_last_info != NEW.mcInfo THEN
        IF v_last_info NOT IN ('Mesin Running', 'Running', 'Mesin Off', 'Off') THEN
            
            SELECT id INTO v_diff_id 
            FROM log_quality 
            WHERE mcID = NEW.mcID AND id < NEW.id AND mcInfo != v_last_info 
            ORDER BY id DESC LIMIT 1;

            IF v_diff_id IS NULL THEN
                SET v_diff_id = 0;
            END IF;

            SELECT timestamp INTO v_start_time 
            FROM log_quality 
            WHERE mcID = NEW.mcID AND id > v_diff_id AND id < NEW.id 
            ORDER BY id ASC LIMIT 1;

            IF v_start_time IS NOT NULL THEN
                SET v_durasi = TIMESTAMPDIFF(SECOND, v_start_time, NEW.timestamp);
                IF v_durasi > 0 THEN
                    VALUES (NEW.mcID, v_last_info, v_durasi, NEW.timestamp);
                END IF;
            END IF;
        END IF;
    END IF;
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `before_log_quality_insert`;
DELIMITER $$
CREATE TRIGGER `before_log_quality_insert` BEFORE INSERT ON `log_quality` FOR EACH ROW BEGIN
    DECLARE v_cavity INT DEFAULT 1;
    DECLARE v_last_raw INT DEFAULT NULL;
    DECLARE v_last_db INT DEFAULT NULL;
    DECLARE v_delta INT DEFAULT 0;
    DECLARE v_qty_added INT DEFAULT 0;
    DECLARE v_saved_kode VARCHAR(50);
    DECLARE v_saved_op VARCHAR(50);

    
    
    IF (NEW.kode_proses IS NULL OR NEW.kode_proses = '') OR (NEW.op_NIK IS NULL OR NEW.op_NIK = '') THEN
        SELECT last_kode_proses, last_op_nik INTO v_saved_kode, v_saved_op
        FROM master_mesin
        WHERE mcID = NEW.mcID OR id_mesin = NEW.mcID LIMIT 1;
        
        IF (NEW.kode_proses IS NULL OR NEW.kode_proses = '') AND v_saved_kode IS NOT NULL THEN
            SET NEW.kode_proses = v_saved_kode;
        END IF;
        
        IF (NEW.op_NIK IS NULL OR NEW.op_NIK = '') AND v_saved_op IS NOT NULL THEN
            SET NEW.op_NIK = v_saved_op;
        END IF;
    END IF;

    
    IF (NEW.kode_proses IS NOT NULL AND NEW.kode_proses != '') OR (NEW.op_NIK IS NOT NULL AND NEW.op_NIK != '') THEN
        UPDATE master_mesin 
        SET last_kode_proses = COALESCE(NULLIF(NEW.kode_proses, ''), last_kode_proses),
            last_op_nik = COALESCE(NULLIF(NEW.op_NIK, ''), last_op_nik)
        WHERE mcID = NEW.mcID OR id_mesin = NEW.mcID;
    END IF;

    
    IF NEW.kode_proses IS NOT NULL AND NEW.kode_proses != '' THEN
        SELECT cavity INTO v_cavity FROM master_ct WHERE kode = NEW.kode_proses LIMIT 1;
        IF v_cavity IS NULL OR v_cavity < 1 THEN
            SET v_cavity = 1;
        END IF;
    END IF;

    
    SELECT raw_prodCount, prodCount INTO v_last_raw, v_last_db 
    FROM log_quality 
    WHERE mcID = NEW.mcID 
    ORDER BY id DESC LIMIT 1;

    IF v_last_raw IS NULL OR v_last_db IS NULL THEN
        SELECT offset_raw_produksi, offset_produksi INTO v_last_raw, v_last_db
        FROM master_mesin
        WHERE mcID = NEW.mcID OR id_mesin = NEW.mcID LIMIT 1;
        
        IF v_last_raw IS NULL THEN SET v_last_raw = 0; END IF;
        IF v_last_db IS NULL THEN SET v_last_db = 0; END IF;
    END IF;

    SET v_delta = NEW.prodCount - v_last_raw;

    IF v_delta < 0 THEN
        SET v_qty_added = NEW.prodCount;
    ELSEIF v_delta > 0 THEN
        SET v_qty_added = v_delta;
    ELSE
        SET v_qty_added = 0;
    END IF;

    SET NEW.raw_prodCount = NEW.prodCount;
    SET NEW.prodCount = v_last_db + (v_qty_added * v_cavity);
END
$$
DELIMITER ;

